fun chargeWithRetries(channel: Channel, paymentId: String, cents: Long): ChargeReply {
    val request = ChargeRequest(paymentId, cents, UUID.randomUUID().toString()) // one key, made once
    val retryable = setOf(Status.Code.UNAVAILABLE, Status.Code.DEADLINE_EXCEEDED)
    var attempt = 0
    while (true) {
        attempt++
        val options = CallOptions.DEFAULT.withDeadlineAfter(200, TimeUnit.MILLISECONDS)
        try {
            return ClientCalls.blockingUnaryCall(channel, ChargeRpc.CHARGE, options, request)
        } catch (e: StatusRuntimeException) {
            if (e.status.code !in retryable || attempt >= 4) throw e
            Thread.sleep(Random.nextLong(0, (10L shl (attempt - 1)) + 1)) // full jitter
        }
    }
}
